"""alpha.py -- SESSION 64. THE INSTRUMENT OF THE 'WHY'.

Löwdin asks WHY n+l. This reparametrises the question. Order channels by n + a*l and
ask what the field permits for `a`. Hydrogen has a = 0 EXACTLY (E(2s)=E(2p) to 2 uHa,
s63 Rung 5); Madelung asserts a = 1. So 'why n+l' becomes 'why does a land on 1'.

TWO MEASURES, and they answer different questions.

  interval   For each Z, every pair of channels the field ranks gives one inequality
             in `a`. Intersect them. Reports what the ORDERING permits. Ordinal.
  ratio      a = [D(n,l+1) - D(n,l)] / [D(n+1,l) - D(n,l)]
             The cost of one unit of l in units of one unit of n. Continuous, and it
             is the quantity that decides a tie-break pair: channels (n,l+1) and
             (n+1,l) share n+l, and (n,l+1) -- the LOWER n, which Madelung requires
             first -- wins IFF a < 1. **a = 1 IS THE CRITICAL VALUE OF THE TIE-BREAK
             CLAUSE AND IS NOTHING ELSE.** Verified: every a=1 bound found by the
             interval method, in both directions, comes from an equal-n+l pair. 100%.

usage: python3 alpha.py intervals        per-Z interval, all pairs and penetrating only
       python3 alpha.py ratios           a at every (Z,n,l) the sealed chain supports
       python3 alpha.py sources          which channel pairs generate the a=1 bounds
       python3 alpha.py iso [Znuc ...]   isoelectronic sweep, Ne core, RUNS SOLVES
       python3 alpha.py blocks           THE s65 TEST -- see FINDING-ALPHA-THE-WHY §5
Run from rt/ with PYTHONPATH=. for `iso`; the others need only nlchain.jsonl.
"""
import sys, os, json, statistics as st

HERE = os.path.dirname(os.path.abspath(__file__))
CHAIN = os.path.join(HERE, '..', 'rt', 'nlchain.jsonl')
T = lambda n, l: f"{n}{'spdfg'[l]}"
nl = lambda t: (int(t[0]), 'spdfg'.index(t[1]))


def load():
    return {json.loads(l)['Z']: json.loads(l) for l in open(CHAIN)}


def cfg_at(Z, rows):
    d = {(1, 0): 1}
    for z in range(2, Z + 1):
        n, l = rows[z]['ent_nl']; d[(n, l)] = d.get((n, l), 0) + 1
    return d


def rho(t, D, q=1):
    """depth as a multiple of the hydrogenic value at the same n. 1.0 = expelled
    beyond the centrifugal barrier, seeing the cation as a point charge q."""
    n, _ = nl(t); return D / (-0.5 * q * q / n ** 2)


def interval(order, pen_only=False):
    ch = [(t,) + nl(t) for t, D in order if (not pen_only or rho(t, D) > 1.5)]
    lo, hi = -9e9, 9e9
    for i in range(len(ch)):
        for j in range(i + 1, len(ch)):
            _, ni, li = ch[i]; _, nj, lj = ch[j]     # field ranks i deeper than j
            dn, dl = ni - nj, lj - li
            if dl > 0: lo = max(lo, dn / dl)
            elif dl < 0: hi = min(hi, dn / dl)
    return lo, hi, len(ch)


def ratios(rows):
    out = []
    for Z in sorted(rows):
        if Z < 3: continue
        D = dict(rows[Z]['order']); c = cfg_at(Z - 1, rows)
        N = lambda l: sum(1 for (n, ll) in c if ll == l)
        for n in range(2, 8):
            for l in range(0, 3):
                a, b, cc = T(n, l), T(n, l + 1), T(n + 1, l)
                if a in D and b in D and cc in D:
                    den = D[cc] - D[a]
                    if abs(den) > 1e-4:
                        out.append((Z, n, l, (D[b] - D[a]) / den, N(l) - N(l + 1)))
    return out


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else 'ratios'
    if cmd == 'iso':
        os.environ.setdefault("SIC_NOCLAMP", "1"); os.environ.setdefault("SUBCELL", "1")
        import hfc2 as H, nlguard as NG
        H.CORR = False
        CORE = [(1, 0, 2.0), (2, 0, 2.0), (2, 1, 6.0)]      # Ne core, held FIXED
        CH = [(3, 0), (3, 1), (3, 2), (4, 0), (4, 1)]
        def add(cfg, ch):
            d = {(n, l): q for n, l, q in cfg}; d[ch] = d.get(ch, 0) + 1
            return [(n, l, q) for (n, l), q in sorted(d.items())]
        zs = [int(x) for x in sys.argv[2:]] or [11, 13, 16, 20, 26]
        print(" Znuc  q   a(s->p)  a(p->d)")
        for Znuc in zs:
            g = NG.run_guarded(Znuc, CORE, 'ref')
            if not g['conv']: print(f"{Znuc:>5}  ref NO-DATA"); continue
            E0 = g['E']; D = {}
            for ch in CH:
                gg = NG.run_guarded(Znuc, add(CORE, ch), 'x')
                D[ch] = (gg['E'] - E0) if gg['conv'] else None
            try:
                a1 = (D[(3, 1)] - D[(3, 0)]) / (D[(4, 0)] - D[(3, 0)])
                a2 = (D[(3, 2)] - D[(3, 1)]) / (D[(4, 1)] - D[(3, 1)])
                print(f"{Znuc:>5} {Znuc-10:>2}  {a1:7.4f}  {a2:7.4f}")
            except TypeError:
                print(f"{Znuc:>5} {Znuc-10:>2}  incomplete (a channel did not converge)")
        return

    rows = load()
    if cmd == 'intervals':
        print("   Z   all-pairs        penetrating-only   1 in pen?  ent")
        for Z in sorted(rows):
            lo, hi, _ = interval(rows[Z]['order'])
            lp, hp, npen = interval(rows[Z]['order'], True)
            if npen < 2: continue
            f = lambda a, b: f"[{a:6.2f},{b:6.2f}]" if b < 1e8 else f"[{a:6.2f},  inf]"
            print(f"{Z:>5}  {f(lo,hi)}  {f(lp,hp)}      {'yes' if lp<=1<=hp else 'NO '}    {rows[Z]['ent']}")
    elif cmd == 'sources':
        src = {}
        for Z in sorted(rows):
            ch = [(t,) + nl(t) for t, D in rows[Z]['order'] if rho(t, D) > 1.5]
            for i in range(len(ch)):
                for j in range(i + 1, len(ch)):
                    ti, ni, li = ch[i]; tj, nj, lj = ch[j]; dn, dl = ni - nj, lj - li
                    if dl and abs(dn / dl - 1) < 1e-9:
                        k = (ti, tj, (ni + li) == (nj + lj), 'a<=1' if dl < 0 else 'a>=1')
                        src[k] = src.get(k, 0) + 1
        print("  pair            equal n+l   forces   rows")
        for k, v in sorted(src.items(), key=lambda x: -x[1])[:14]:
            print(f"  {k[0]:>3} over {k[1]:>3}     {str(k[2]):>5}    {k[3]:>5}   {v}")
        print(f"\n  equal-n+l share of all a=1 bounds: "
              f"{sum(v for k,v in src.items() if k[2])/sum(src.values()):.3f}")
    elif cmd == 'blocks':
        # THE s65 TEST. For each equal-n+l block, the tie-break pair is
